{
  "findings": [
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that even with the strictest chat setting ('no one'), in-game chats can still occur if the game itself includes chat.",
      "stance": "risk",
      "quote": "even when chat is set to \"no one,\" if a mini-game has chat built into the game itself, it can't be disabled."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that experience chat controls who your child can communicate with inside supported experiences, and parents should use the strictest settings to limit interactions with strangers.",
      "stance": "mitigation",
      "quote": "Parents who want to limit interactions with strangers should use the strictest communication settings available."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that experience direct chat refers to private or one-to-one direct message features within some games, and availability depends on age, parental controls, and account protections.",
      "stance": "risk",
      "quote": "Availability depends on factors such as age, parental controls, account protections, and the communication tools supported by the game."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that party chat allows grouping with friends and chatting within a shared experience, and parents should ensure anyone added is truly a friend.",
      "stance": "mitigation",
      "quote": "Keep in mind that if the settings allow your child to talk to their \"friends\" within party chat, you should ensure anyone your child adds is truly their friend and not an unfamiliar person."
    },
    {
      "ref": "[D522]",
      "area": "contact",
      "claim": "A parent reports that kids can bypass disabled chats by writing text on signs that their avatar can hold up to communicate to everyone in the same game.",
      "stance": "risk",
      "quote": "Any user can write text on \"signs\" that their avatar can hold up to communicate a message to everyone who is playing the same game as them, regardless of age."
    },
    {
      "ref": "[D522]",
      "area": "voice",
      "claim": "A parent reports that voice chat may not be available for unverified accounts and recommends disabling it for young kids to limit communication with unfamiliar people.",
      "stance": "mitigation",
      "quote": "For young kids, we recommend disabling voice chat to limit communication with unfamiliar people—particularly because kids can be exposed to a stream of vulgar audio from other kids and adults."
    },
    {
      "ref": "[D522]",
      "area": "privacy",
      "claim": "A parent reports that visibility settings let you choose who can see your kid's current experience and join them, with options of \"friends\" or \"no one\".",
      "stance": "mitigation",
      "quote": "You can select \"friends,\" or \"no one\" if you're unsure about who your kid may be friends with on Roblox."
    },
    {
      "ref": "[D522]",
      "area": "privacy",
      "claim": "A parent reports that private servers can be restricted to friends or turned off entirely to limit who can join your child's server.",
      "stance": "mitigation",
      "quote": "To limit who can join your child's private servers, and whose servers they can join, choose either \"Friends\" or \"Off.\""
    },
    {
      "ref": "[D522]",
      "area": "money",
      "claim": "A parent reports that you can set a monthly spending limit on how much money your child can spend on Roblox.",
      "stance": "mitigation",
      "quote": "You can set a monthly spending limit on how much money your child can spend on Roblox."
    },
    {
      "ref": "[D522]",
      "area": "data",
      "claim": "A parent reports that you can turn off ad personalization and data selling, and turn off data sharing.",
      "stance": "mitigation",
      "quote": "You can turn off ad personalization and data selling. You can also turn off data sharing."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate requires a government-issued ID or credit card verification before parental privileges are enabled.",
      "stance": "mitigation",
      "quote": "Parents are asked to verify themselves using a government-issued ID or credit card before privileges are enabled."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that some experiences labeled 5+ still contain intense violence or sensitive issues, such as fiery car accidents or prompts to shoot or save an officer.",
      "stance": "risk",
      "quote": "Within seconds, this \"Street Code\" game showed an intense, fiery car accident and prompted the player to decide whether to shoot or save an officer."
    },
    {
      "ref": "[D522]",
      "area": "content",
      "claim": "A parent reports that experiences labeled as containing sensitive issues are blocked by default for users under 16, but parents can change this setting.",
      "stance": "mitigation",
      "quote": "By default, users under 16 cannot access experiences that are labeled as including sensitive issues, though parents can change this in the Sensitive issues settings."
    },
    {
      "ref": "[D522]",
      "area": "age_gating",
      "claim": "A parent reports that the age gate works in practice, as users under 16 are blocked from accessing experiences labeled with sensitive issues unless parents change the setting.",
      "stance": "neutral",
      "quote": "By default, users under 16 cannot access experiences that are labeled as including sensitive issues, though parents can change this in the Sensitive issues settings."
    }
  ]
}
